package com.bike.server.system;
import java.time.LocalDateTime;
public class UserView { private Long id; private String username; private String displayName; private String userType; private Long agentId; private Long workstationId; private boolean enabled; private boolean mustChangePassword; private LocalDateTime lastLoginAt; private LocalDateTime createdAt; public Long getId(){return id;} public void setId(Long v){id=v;} public String getUsername(){return username;} public void setUsername(String v){username=v;} public String getDisplayName(){return displayName;} public void setDisplayName(String v){displayName=v;} public String getUserType(){return userType;} public void setUserType(String v){userType=v;} public Long getAgentId(){return agentId;} public void setAgentId(Long v){agentId=v;} public Long getWorkstationId(){return workstationId;} public void setWorkstationId(Long v){workstationId=v;} public boolean isEnabled(){return enabled;} public void setEnabled(boolean v){enabled=v;} public boolean isMustChangePassword(){return mustChangePassword;} public void setMustChangePassword(boolean v){mustChangePassword=v;} public LocalDateTime getLastLoginAt(){return lastLoginAt;} public void setLastLoginAt(LocalDateTime v){lastLoginAt=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;} }
